#!/bin/bash
# Task 185-w22-drift -- meshsim sim/ WORKER22 (branch sim-w22 08395f12), for the docs session's spec items 62 and 70
# (the owner's agreement). tests/p4_drift.cpp runs engine-full's data sets as EngineTest full runs them (the 16-group
# all-to-alls on uniform Data(7, 65536), zipfraw, trace and one99 at gaps 4, 0, 8; the local radix sort at 64 x 16,384
# keys, its augmenting pass and four bucket passes; 0/+1 skew) and records per run: the tiles with ERRORS [3] set (drift,
# 4.13, the register block's condition from the AG's drift event), the AG's drift events summed over the tiles, the send
# port's token-wait cycles summed (Injection::token_waits), the read side's window-full cycles summed (the SRAM read queue
# waiting with no token free), and the run's cycles. A control row first (EngineTest's drift case, where drift is
# expected); a run with drift is run again cycle by cycle to name each tile's first drift cycle. The quick smoke is run
# first and must give EngineTest's quick figures (3180, 3120; 4117 x 5, 20585) with the control's drift on tile 7.
# The machine recorded (D21: sim/tools/machine.sh). clang, the suite build. Not timing. From an embedded kit. Writes only
# results/185-w22-drift/. Scratch in /tmp, removed first and at the end. Safe to re-run from the start.
set -u
cd "$(dirname "$0")/.."
REPO=$PWD; RES=$REPO/results/185-w22-drift; mkdir -p "$RES"
W=/tmp/w22-185; rm -rf "$W"; mkdir -p "$W"
trap 'rm -rf "$W"' EXIT
sed -n '/^__KIT_BEGIN__$/,/^__KIT_END__$/p' "$0" | sed '1d;$d' | base64 -d > "$W/kit.tgz" || exit 2
GOT=$(sha256sum "$W/kit.tgz" | cut -d' ' -f1); echo "kit sha256 $GOT"
[ "$GOT" = "45a61b2863857a859ffa23d725b770afd5f8b552c8e2382517dd02dc86f1a0ac" ] || { echo "kit sha256 mismatch (want 45a61b2863857a859ffa23d725b770afd5f8b552c8e2382517dd02dc86f1a0ac)"; exit 2; }
tar -xzf "$W/kit.tgz" -C "$W" || exit 2
(cd "$W/kit" && sha256sum -c --quiet HASHES) || { echo "kit files differ from HASHES"; exit 2; }
KS=$W/kit/sim
FAIL=0
verdict() { echo "VERDICT $1: $2"; echo "$1 $2" >> "$RES/VERDICTS"; [ "$2" = PASS ] || FAIL=1; }
: > "$RES/VERDICTS"
echo "kit: $(cat $W/kit/VERSION); host $(hostname)"
bash "$KS/tools/machine.sh" record "$RES/machine.txt" > /dev/null 2>&1; cat "$RES/machine.txt"
cd "$KS"
make MODE=suite -j8 build/clang-suite/p4_drift > "$RES/build.log" 2>&1 && verdict build PASS || { tail -20 "$RES/build.log"; verdict build FAIL; echo FAILED; exit 1; }
build/clang-suite/p4_drift quick > "$RES/quick.txt" 2>&1; cat "$RES/quick.txt"
grep -q "t7@" "$RES/quick.txt" && grep -q " 3180$" "$RES/quick.txt" && grep -q " 3120$" "$RES/quick.txt" && grep -q " 20585$" "$RES/quick.txt" \
  && verdict smoke PASS || verdict smoke FAIL
t0=$(date +%s); build/clang-suite/p4_drift > "$RES/drift.txt" 2>&1; rc=$?; echo "full: exit $rc in $(( $(date +%s) - t0 )) s"
cat "$RES/drift.txt"
[ $rc = 0 ] && grep -q "radix sort (16384 keys)     total" "$RES/drift.txt" && verdict full PASS || verdict full FAIL
echo; cat "$RES/VERDICTS"
[ $FAIL = 0 ] && { echo DONE; exit 0; } || { echo FAILED; exit 1; }
